import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cz0TtJv6.js";const g=JSON.parse('{"title":"Dashboard guide","description":"Tab-by-tab tour of the DLMM Bot ops dashboard — Overview, Positions, Activity, Analytics, Research, Errors, Changes, Settings, Wiki — plus the setup wizard, encrypted wallet, and HALT.","frontmatter":{"title":"Dashboard guide","description":"Tab-by-tab tour of the DLMM Bot ops dashboard — Overview, Positions, Activity, Analytics, Research, Errors, Changes, Settings, Wiki — plus the setup wizard, encrypted wallet, and HALT."},"headers":[],"relativePath":"dashboard.md","filePath":"dashboard.md","lastUpdated":1786724746000}'),s={name:"dashboard.md"};function n(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-guide" tabindex="-1">Dashboard guide <a class="header-anchor" href="#dashboard-guide" aria-label="Permalink to &quot;Dashboard guide&quot;">​</a></h1><p>Live window onto the farmer: ledger, settings, wizard, encrypted wallet. On Railway it’s your public HTTPS URL; locally <code>http://localhost:8787/?token=…</code>.</p><p><strong>Overview</strong> for “am I ok?”, <strong>Positions</strong> for open trades, <strong>Activity</strong> when something looks off, <strong>Wiki</strong> when you forget a rule.</p><p class="cta-row"><a class="doc-btn ghost" href="./easy">Easy setup</a><a class="doc-btn ghost" href="./api-keys">API keys</a><a class="doc-btn ghost" href="./profiles">Settings profiles</a></p><h2 id="first-login-the-setup-wizard" tabindex="-1">First login: the setup wizard <a class="header-anchor" href="#first-login-the-setup-wizard" aria-label="Permalink to &quot;First login: the setup wizard&quot;">​</a></h2><p>When RPC and wallet are missing, first login walks through:</p><ol><li><strong>Terms &amp; risk waiver</strong> — scroll and accept <a href="./terms">Terms</a> (required; also shown to existing installs that have not accepted yet).</li><li><strong>Dash token</strong> — Railway variable <code>DASH_TOKEN</code> (≥24 random chars). Not the truncated prefix in deploy logs.</li><li><strong>RPC &amp; APIs</strong> — Helius mainnet URL, Jupiter key, optional GMGN.</li><li><strong>Wallet</strong> — create a keypair or import a Phantom base58 key. Encrypted with a passphrase (AES-256-GCM) as <code>wallet.enc.json</code> on your volume. Password retype + one-time backup.</li><li><strong>Paper or live</strong> — live still needs the <a href="./risk#paper-first-the-promotion-gate">double lock</a>.</li><li>Optionally <strong>unlock</strong> into <code>.env</code> (or set <code>WALLET_PASSPHRASE</code> on Railway to auto-unlock on boot).</li></ol><p class="note bad">Fresh burner only — never your main wallet.</p><h2 id="header-the-health-lights" tabindex="-1">Header: the health lights <a class="header-anchor" href="#header-the-health-lights" aria-label="Permalink to &quot;Header: the health lights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pill / control</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>ON/OFF</strong></td><td>Soft pause. OFF = no new trades, no exits initiated; positions stay open (<code>PAUSE</code> file).</td></tr><tr><td><strong>HALT</strong> (red)</td><td>Emergency close-all: confirm with dash token → close every open, swap to SOL, idle until Resume.</td></tr><tr><td><strong>HB</strong></td><td>Seconds since the last finished tick — green = fresh, red = stuck. Tick age, not wall clock.</td></tr><tr><td><strong>WS</strong></td><td>This browser’s live websocket.</td></tr><tr><td><strong>PAPER / LIVE</strong></td><td>Current mode.</td></tr><tr><td><strong>BRAKE</strong></td><td>Cluster brake has paused new entries.</td></tr><tr><td><strong>Build pill + Auto switch</strong></td><td>Release, branch, SHA, sync. Auto on/off chooses auto-pull vs Approve-on-Changes.</td></tr><tr><td><strong>Host / wallet chip</strong></td><td>Which machine, and the wallet when known.</td></tr></tbody></table><h2 id="the-tabs" tabindex="-1">The tabs <a class="header-anchor" href="#the-tabs" aria-label="Permalink to &quot;The tabs&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Account value, open profit with slot occupancy (e.g. <code>3 of 5 · 2 free</code>), equity chart. Header ON/OFF and HALT answer “is everything fine?”</p><h3 id="positions" tabindex="-1">Positions <a class="header-anchor" href="#positions" aria-label="Permalink to &quot;Positions&quot;">​</a></h3><p>Open positions (slot badge) and recent closes. Range bar: <strong>purple ≈ SOL still waiting</strong> below price, <strong>blue ≈ already converted to token</strong>. Close rows split <strong>Move</strong> (deposit/IL) from <strong>Fees</strong>.</p><h3 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h3><p>Entries, exits, claims, skips, follow-chain events. Green = inflows/wins, blue = capital deployed, red = losses. On-chain rows link to Solscan.</p><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h3><p>Exits by reason (P0–P5), performance by sleeve, skip stats. Check whether a knob change did anything before touching the next one.</p><h3 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h3><p>Public X (Twitter) credits for people whose playbooks informed the strategy. <strong>Not partners, not trade signals.</strong></p><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><p>Structured failures over WebSocket. <strong>Transient</strong> (API blip), <strong>Degraded</strong> (partial), <strong>Needs attention</strong> — plus stack, mint/pool, copy-dump, GitHub issue shortcut.</p><h3 id="changes-changelog" tabindex="-1">Changes (Changelog) <a class="header-anchor" href="#changes-changelog" aria-label="Permalink to &quot;Changes (Changelog)&quot;">​</a></h3><p>Pending git updates with risk chips (<code>strategy</code> / <code>deps</code> / <code>deploy</code> / <code>core</code> / <code>dash</code> / <code>docs</code>). Auto-update <strong>on</strong> (default): watcher pulls, rebuilds, restarts. <strong>Off</strong>: BEHIND + <strong>Approve</strong> pulls that tip.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong>Bot settings</strong> — sizing, brakes, vetting, sleeves → <code>data/config.toml</code>, hot-reloaded. Home of <a href="./profiles">Profiles</a>. Packs never flip paper/live or touch secrets. <a href="./fees">Fees</a> stay fixed.</li><li><strong>Wallet &amp; secrets</strong> — vault, <code>RPC_URL</code>, API keys, auto-update preference.</li></ul><p>Writes go to the <code>data/</code> volume, never git — a DIRTY build pill means real code drift.</p><h3 id="wiki" tabindex="-1">Wiki <a class="header-anchor" href="#wiki" aria-label="Permalink to &quot;Wiki&quot;">​</a></h3><p>In-dashboard operator manual — a friendlier mirror of <a href="https://github.com/CryptoGnome/dlmmbot/blob/main/STRATEGY.md" target="_blank" rel="noreferrer">STRATEGY.md</a>. Kept in sync when behavior changes.</p><h2 id="encrypted-wallet" tabindex="-1">Encrypted wallet <a class="header-anchor" href="#encrypted-wallet" aria-label="Permalink to &quot;Encrypted wallet&quot;">​</a></h2><ul><li><strong>Create</strong> — fresh keypair in the browser, encrypts with your passphrase, stores <code>wallet.enc.json</code>.</li><li><strong>Import</strong> — Phantom base58 private key (a burner); same encryption. Plaintext never lands on disk.</li><li><strong>Unlock</strong> — decrypts into runtime <code>.env</code>. On Railway, <code>WALLET_PASSPHRASE</code> auto-unlocks on boot.</li></ul><p>Keys live on <strong>your</strong> volume/host — not hosted custody.</p><h2 id="halting-from-the-dashboard" tabindex="-1">Halting from the dashboard <a class="header-anchor" href="#halting-from-the-dashboard" aria-label="Permalink to &quot;Halting from the dashboard&quot;">​</a></h2><p>Red <strong>HALT</strong> asks for your dash token, then writes the same <code>HALT</code> file as <code>npm run halt</code>: close everything, swap residuals to SOL, idle. <strong>Resume</strong> clears it. Use ON/OFF to stop <em>new</em> activity without closing the book — <a href="./risk#halt-vs-pause-vs-off">HALT vs PAUSE vs OFF</a>.</p><p class="cta-row"><a class="doc-btn ghost" href="./advanced">Advanced setup</a><a class="doc-btn ghost" href="./configuration">Configuration</a><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a></p>',36)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
